/**
 * Resolves a user-supplied path against the current working directory.
 *
 * `path.resolve` rather than `path.join`: joining strips the leading separator
 * from an absolute path, so `/tmp/x.json` would become `<cwd>/tmp/x.json`.
 * These paths come from the command line, so an absolute one has to be
 * honoured as given.
 */
export declare function getAbsolutePath(p: string): string;
/** Check if the given folder exists. */
export declare function isFolderExists(folderPath: string): Promise<boolean>;
/** Check if the given file exists. */
export declare function isFileExists(folderPath: string): Promise<boolean>;
/** Create a new folder at the specific path */
export declare function createFolder(folderPath: string): Promise<void>;
/** Remove a folder at the specified location */
export declare function removeFolder(folderPath: string): Promise<void>;
/** List files within a directory */
export declare function listFiles(folderPath: string): Promise<string[]>;
/** Check if the given path is a file. */
export declare function isFile(filePath: string): Promise<boolean>;
/** Load data from a file in JSON format. */
export declare function loadFileData<T>(filePath: string): Promise<T | undefined>;
/** Save data to a file in JSON format. */
export declare function saveToFile<T>(filePath: string, data: T): Promise<void>;
/**
 * Atomically creates a private temporary directory and returns its path.
 *
 * The directory is created by a single `mkdtemp` call directly under the system
 * temp root, with a random name and, on POSIX, mode 0700. Composing the path
 * from a fixed prefix and materialising it later with a recursive `mkdir` would
 * leave a predictable intermediate directory that another local user can
 * pre-create or replace with a symlink, placing everything written afterwards
 * under their control.
 *
 * @param prefix Name prefix for the directory. Must be a single path segment.
 * @returns The absolute path of the newly created directory.
 */
export declare function createTempDir(prefix: string): Promise<string>;
/**
 * Try to find a file recursively in the given folder.
 * @param sourceFolder The folder to search in.
 * @param fileName The name of the file to find.
 * @param maxIterations The maximum number of iterations to perform.
 * @returns The absolute path of the found file.
 * @throws Error if the file is not found after the maximum number of
 *     iterations.
 */
export declare function tryToFindFileRecursively(sourceFolder: string, fileName: string, maxIterations: number): Promise<string>;
